buildpipeline.env_vars:
${merge(
    {
      ENV: var.env
      SERVICE_NAME: var.service_name
      NEXT_PUBLIC_SERVER_URL:  "https://${var.subdomain}.${var.hosted_zone_name}"
      // NEXT_PUBLIC_STRIPE_PUBLIC_KEY: var.secrets.drawnby_frontend_REACT_APP_STRIPE_PUBLIC_KEY
      AUTH_CLIENT_ID: var.secrets.chaospixel_lambda_service_AUTH_CLIENT_ID
      AUTH_USER_POOL_ID: var.secrets.chaospixel_lambda_service_AUTH_USER_POOL_ID
      S3_BUCKET: module.cloudfront.s3_bucket.bucket
      PUBLIC_ASSET_URL: "https://${local.cloudfront_subdomain}.${var.hosted_zone_name}"
      # REPOSITORY_URI: aws_ecr_repository.ecr_repository.repository_url
    },
    var.extra_env_vars
  )}

code_build_role.assume_role_policy:
${jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = ["codebuild.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })}

inline_policy.policy:
${jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Resource = [
            "arn:aws:logs:${var.region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/codebuild/${join("-", [var.service_name, var.env, var.region])}",
            "arn:aws:logs:${var.region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/codebuild/${join("-", [var.service_name, var.env, var.region])}:**"
          ]
        },
        {
          Effect = "Allow"
          Action = [
            "s3:PutObject",
            "s3:GetObject",
            "s3:GetObjectVersion",
            "s3:GetBucketAcl",
            "s3:GetBucketLocation"
          ]
          Resource = [
            "arn:aws:s3:::${var.code_pipeline_artifact_store_bucket}/*",
            "arn:aws:s3:::${var.code_pipeline_artifact_store_bucket}/"
          ]
        },
        {
          Effect = "Allow"
          Action = [
            "codebuild:StartBuild"
          ]
          Resource = [
            "arn:aws:codebuild:${var.region}:${data.aws_caller_identity.current.account_id}:project/${join("-", [var.service_name, var.env, var.region])}"
          ]
        },
        {
          Effect = "Allow"
          Action = [
            "ecr:GetLifecyclePolicyPreview",
            "ecr:GetDownloadUrlForLayer",
            "ecr:ListTagsForResource",
            "ecr:UploadLayerPart",
            "ecr:ListImages",
            "ecr:PutImage",
            "ecr:BatchGetImage",
            "ecr:CompleteLayerUpload",
            "ecr:DescribeImages",
            "ecr:TagResource",
            "ecr:DescribeRepositories",
            "ecr:InitiateLayerUpload",
            "ecr:BatchCheckLayerAvailability",
            "ecr:GetRepositoryPolicy",
            "ecr:GetLifecyclePolicy"
          ]
          Resource = ["arn:aws:ecr:${var.region}:${data.aws_caller_identity.current.account_id}:repository/*"]
        },
        {
          "Effect": "Allow",
          "Action": [
            "ecr:GetAuthorizationToken"
          ],
          "Resource": "*"
        },
        {
          "Effect": "Allow",
          "Action": [
     /*       "ec2:DescribeSecurityGroups",
            "ec2:DescribeSubnets",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DeleteNetworkInterface",
            "ec2:CreateNetworkInterfacePermission",*/
            "iam:PassRole",
            "ec2:CreateNetworkInterface",
            "ec2:ModifySnapshotAttribute",
            "ec2:DetachNetworkInterface",
            "ec2:DescribeVpcs",
            "ec2:DescribeSubnets",
            "ec2:DescribeSecurityGroups",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DescribeDhcpOptions",
            "ec2:DeleteNetworkInterface",
            "ec2:CreateNetworkInterface",

            "ec2:DescribeDhcpOptions"
          ],
          "Resource": "*"
        },
        {
          "Sid": "VisualEditor0",
          "Effect": "Allow",
          "Action": "ec2:CreateNetworkInterfacePermission",
          "Resource": "arn:aws:ec2:${var.region}:${data.aws_caller_identity.current.account_id}:network-interface/*",
          /*"Condition": {
            "StringEquals": {
              "ec2:Subnet": [
                [for o in var.private_subnet_mappings : o.arn]
              ],
              "ec2:AuthorizedService": "codebuild.amazonaws.com"
            }
          }*/
        }
      ]
    })}

code_pipeline_service_role.assume_role_policy:
${jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = ["codepipeline.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })}

inline_policy.policy:
${jsonencode({
      Version   = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "codestar-connections:UseConnection",
            "codestar-connections:StartOAuthHandshake",
            "codestar-connections:GetInstallationUrl",
            "codestar-connections:GetConnection"
          ]
          Resource = "*"
        },
        {
          Effect = "Allow"
          Action = [
            "codedeploy:CreateDeployment",
            "codedeploy:GetApplicationRevision",
            "codedeploy:GetDeployment",
            "codedeploy:GetDeploymentConfig",
            "codedeploy:RegisterApplicationRevision"
          ]
          Resource = "*"
        },
        {
          Effect = "Allow"
          Action = [
            "codebuild:CreateReportGroup",
            "codebuild:CreateReport",
            "codebuild:UpdateReport",
            "codebuild:BatchPutTestCases",
            "codebuild:BatchGetBuildBatches"
          ]
          Resource = [aws_codebuild_project.codebuild_project.arn]
        },
        {
          Effect = "Allow"
          Action = [
            "codebuild:BatchGetBuilds",
            "codebuild:StartBuild",
            "codebuild:StartBuildBatch"
          ]
          Resource = "*"
        },
        {
          Effect   = "Allow"
          Action   = "iam:PassRole"
          Resource = "*"
        },
        {
          Effect = "Allow"
          Action = [
            "s3:PutObject",
            "s3:GetObject"
          ]
          Resource = "arn:aws:s3:::${var.code_pipeline_artifact_store_bucket}/*"
        }
      ]
    })}

lambda_service.env_vars:
${merge(
    {
      NODE_ENV: var.env
      NEXT_PUBLIC_SERVER_URL:  "https://${var.subdomain}.${var.hosted_zone_name}"
      AUTH_CLIENT_ID: var.secrets.chaospixel_lambda_service_AUTH_CLIENT_ID
      AUTH_USER_POOL_ID: var.secrets.chaospixel_lambda_service_AUTH_USER_POOL_ID
      S3_BUCKET: module.cloudfront.s3_bucket.bucket
      PUBLIC_ASSET_URL: "https://${local.cloudfront_subdomain}.${var.hosted_zone_name}",
      AWS_LAMBDA_EXEC_WRAPPER: "/opt/bootstrap"
      PORT: "8000"
    },
    var.extra_env_vars
  )}

cloudfront_bucket_policy.policy:
${jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "S3"
        Effect    = "Allow"
        Principal = "*" // aws_iam_policy.codebuild_iam_policy.arn
        Action    = "s3:*"
        Resource  = module.cloudfront.s3_bucket.arn

        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      }
    ]
  })}

